default(0) // manual ordering within a subject\n  isCompleted Boolean   @default(false)\n  completedAt DateTime?\n  // Relative share of the syllabus, e.g. the topic's % of exam marks.\n  weight      Float     @default(1)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  // Revision (lib/review/schedule.ts). Completing a milestone schedules its\n  // first review; each rating moves reviewDueAt out by a stretching interval.\n  // A null reviewDueAt means the topic isn't being revised.\n  confidence     Confidence?\n  reviewDueAt    DateTime?\n  reviewInterval Int? // days\n  reviewCount    Int         @default(0)\n  lastReviewedAt DateTime?\n\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  subjectId String\n\n  tasks Task[]\n\n  @@index([subjectId, order])\n  @@index([reviewDueAt])\n}\n\nmodel Task {\n  id            String      @id @default(uuid())\n  title         String\n  description   String? // markdown notes for the task\n  isCompleted   Boolean     @default(false)\n  completedAt   DateTime?\n  dueDate       DateTime?\n  priority      Priority    @default(MEDIUM)\n  estimatedTime Int? // estimate in minutes\n  timeSpent     Int? // total actual minutes (updated on timer stop)\n  recurrence    Recurrence? // null = one-off; otherwise spawns next instance on completion\n  order         Int         @default(0) // manual ordering within its milestone / loose list\n  createdAt     DateTime    @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId String\n\n  // A task always belongs to a subject; a milestone is optional.\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  subjectId String\n\n  milestone   Milestone? @relation(fields: [milestoneId], references: [id], onDelete: SetNull)\n  milestoneId String?\n\n  subtasks      Subtask[]\n  timerSessions TimerSession[]\n\n  // Loose-task list on the